// Goal5749 bounded V4 Callback-IR / Numba-PTX feasibility path.  Verified
// Numba leaves are deterministically composed with the trusted wrapper into
// one OptiX module because ordinary cross-module CUDA device-function linking
// is not part of this OptiX module path.
//
// This file is included inside rtdl_optix.cpp's anonymous namespace.  It is
// intentionally isolated from every V3 builder and workload.  No application
// identity participates in dispatch.

#include "rtdl_optix_v4_particle_template.h"

struct V4CallbackSphere {
    float cx, cy, cz, radius;
    uint32_t item_id;
};

struct V4CallbackLaunchStatus {
    uint32_t status;
    uint32_t stage;
    uint32_t nonce_word;
    uint32_t invocation_mask;
};

struct V4CallbackParams {
    OptixTraversableHandle traversable;
    const V4CallbackSphere* spheres;
    const float* origins_xyz;
    const float* directions_xyz;
    uint32_t sphere_count;
    uint32_t query_count;
    float tmin;
    float tmax;
    uint32_t* output_ids;
    float* output_t;
    V4CallbackLaunchStatus* status;
    unsigned long long* counters;
};

// Goal5751 formal seven-role Callback IR runtime.  These structs are a frozen
// host mirror of the trusted wrapper generated by
// rtdsl.v4_callback_optix_wrapper_codegen.  The native boundary accepts only
// already verified/composed PTX; it never sees Python source or a user
// callable.
struct V4FormalLaunchStatus {
    uint32_t first_error_claimed;
    uint32_t error_code;
    uint32_t stage;
    uint32_t role;
    uint64_t launch_index;
    uint32_t error_site;
    uint32_t effect_tag;
    uint32_t nonce_word;
    uint32_t invocation_mask;
};
static_assert(sizeof(V4FormalLaunchStatus) ==
              sizeof(RtdlV4FormalLaunchStatusLayout),
              "V4 formal status shared layout size mismatch");
static_assert(offsetof(V4FormalLaunchStatus, launch_index) ==
              offsetof(RtdlV4FormalLaunchStatusLayout, launch_index),
              "V4 formal status launch-index offset mismatch");
static_assert(offsetof(V4FormalLaunchStatus, invocation_mask) ==
              offsetof(RtdlV4FormalLaunchStatusLayout, invocation_mask),
              "V4 formal status invocation-mask offset mismatch");

struct V4FormalParams {
    OptixTraversableHandle traversable;
    const V4CallbackSphere* spheres;
    const float* query_x;
    const float* query_y;
    const float* query_z;
    const float* query_tmax;
    uint32_t sphere_count;
    uint32_t query_count;
    uint32_t* output_ids;
    float* output_distance;
    V4FormalLaunchStatus* status;
    unsigned long long* role_counters;
};

// Goal5756 trusted built-in-triangle runtime.  The native boundary consumes
// only compiler-composed PTX and closed typed columns.  It owns the triangle
// GAS/SBT and is intentionally unable to accept a user intersection program.
struct V4TriangleParams {
    OptixTraversableHandle traversable;
    const float* query_ox;
    const float* query_oy;
    const float* query_oz;
    const float* query_dx;
    const float* query_dy;
    const float* query_dz;
    const float* query_tmax;
    const uint32_t* front_values;
    const uint32_t* back_values;
    const float3* vertices;
    const uint3* triangle_indices;
    const uint32_t* boundary_owner;
    uint32_t primitive_count;
    uint32_t query_count;
    uint32_t* output_0;
    uint32_t* output_1;
    uint32_t* output_2;
    uint32_t* observed_primitive_index;
    uint32_t* observed_hit_kind;
    float* observed_barycentric_x;
    float* observed_barycentric_y;
    V4FormalLaunchStatus* status;
    unsigned long long* role_counters;
};

// Goal5833 static built-in-sphere successor.  Unlike the older custom-AABB
// V4CallbackSphere path, this mirror is paired with
// OPTIX_BUILD_INPUT_TYPE_SPHERES and an OptiX built-in IS module.
struct V4SphereParams {
    OptixTraversableHandle traversable;
    const float* query_sx;
    const float* query_sy;
    const float* query_sz;
    const float* query_ex;
    const float* query_ey;
    const float* query_ez;
    const uint32_t* application_ids;
    uint32_t primitive_count;
    uint32_t query_count;
    uint32_t* output_0;
    uint32_t* output_1;
    uint32_t* output_2;
    uint32_t* observed_primitive_index;
    uint32_t* observed_hit_kind;
    float* observed_t;
    V4FormalLaunchStatus* status;
    unsigned long long* role_counters;
};

// Goal5834 uses the same typed query/output/status columns as Goal5833, but a
// distinct device symbol namespace and a physically different curve GAS.
// The host launch record is layout-identical by construction.
using V4CurveParams = V4SphereParams;

// App-neutral accepted-event projection for built-in curves.  One read-only
// owner ID is bound per primitive; the generated any-hit program performs the
// closed Boolean-OR reduction into one owner-sized output column.
struct V4CurveOwnerGroupedParams {
    OptixTraversableHandle traversable;
    const float* query_sx;
    const float* query_sy;
    const float* query_sz;
    const float* query_ex;
    const float* query_ey;
    const float* query_ez;
    const uint32_t* owner_ids;
    uint32_t primitive_count;
    uint32_t query_count;
    uint32_t owner_count;
    uint32_t* owner_hit_bits;
    uint32_t* query_completion_tokens;
    V4FormalLaunchStatus* status;
    unsigned long long* role_counters;
};
static_assert(sizeof(V4CurveOwnerGroupedParams) == 112u,
              "V4 curve owner-grouped launch-parameter layout changed");
static_assert(offsetof(V4CurveOwnerGroupedParams, owner_ids) == 56u,
              "V4 curve owner column offset changed");
static_assert(offsetof(V4CurveOwnerGroupedParams, owner_hit_bits) == 80u,
              "V4 curve owner output offset changed");

// Goal5814 strict-interior Particle template.  This host mirror deliberately
// has no generic built-in-triangle ``boundary_owner`` pointer.  Seven SoA f32
// query columns and three SoA u32 result columns are the exact shared device
// work used by both future matched arms.
struct V4ParticleParams {
    OptixTraversableHandle traversable;
    const float* query_ox;
    const float* query_oy;
    const float* query_oz;
    const float* query_dx;
    const float* query_dy;
    const float* query_dz;
    const float* query_tmax;
    const uint32_t* front_values;
    const uint32_t* back_values;
    uint32_t primitive_count;
    uint32_t query_count;
    uint32_t* output_selected;
    uint32_t* output_neighbor;
    uint32_t* output_face;
    RtdlV4ParticleControl* control;
};
static_assert(sizeof(V4ParticleParams) == 120u,
              "V4 Particle launch-parameter layout changed");
static_assert(offsetof(V4ParticleParams, query_ox) == 8u,
              "V4 Particle query-column offset changed");
static_assert(offsetof(V4ParticleParams, front_values) == 64u,
              "V4 Particle front-value offset changed");
static_assert(offsetof(V4ParticleParams, primitive_count) == 80u,
              "V4 Particle cardinality offset changed");
static_assert(offsetof(V4ParticleParams, output_selected) == 88u,
              "V4 Particle output offset changed");
static_assert(offsetof(V4ParticleParams, control) == 112u,
              "V4 Particle control offset changed");

// Goal5759 successor built-in-triangle metadata/event route.  This remains a
// closed typed ABI: OptiX owns triangle intersection, Callback IR owns per-hit
// decisions, and the host-side compiler-owned partner owns the final checked
// algebra.  There is no user intersection or reducer-function parameter.
struct V4TriangleReductionParams {
    OptixTraversableHandle traversable;
    const float* query_ox;
    const float* query_oy;
    const float* query_oz;
    const float* query_dx;
    const float* query_dy;
    const float* query_dz;
    const float* query_tmax;
    const uint64_t* primitive_u64;
    const int64_t* primitive_i64;
    const uint32_t* primitive_u32;
    const uint64_t* query_u64;
    const int64_t* query_i64;
    const uint32_t* query_u32;
    uint32_t primitive_count;
    uint32_t query_count;
    uint64_t* per_ray_u64;
    uint64_t event_capacity;
    uint64_t* event_count;
    uint32_t* event_query;
    uint32_t* event_primitive;
    uint64_t* event_stable_id;
    int64_t* event_signed_value;
    uint32_t* event_include;
    V4FormalLaunchStatus* status;
    unsigned long long* role_counters;
    RtdlV4FastTriangleControl* fast_control;
    unsigned long long* fast_product_value;
    const unsigned long long* product_multipliers;
};

// Goal5760 app-neutral capacity-bounded custom-AABB relation route.  The
// native boundary owns the two-pass diagonal coverage, exact launch capacity,
// and OptiX lifetime.  Canonical ordering and duplicate policy remain in the
// verified compiler-owned materializer; partial overflow is never accepted.
struct V4RelationBox {
    float lower_x, lower_y, lower_z, upper_x, upper_y, upper_z;
    uint32_t item_id;
};
struct V4RelationRow { uint32_t source_id, item_id; };
struct V4RelationParams {
    OptixTraversableHandle traversable;
    const V4RelationBox* primitives;
    const V4RelationBox* queries;
    uint32_t primitive_count, query_count, reverse_orientation;
    float minimum_overlap;
    uint64_t event_capacity;
    uint32_t* event_count;
    uint32_t* overflowed;
    V4RelationRow* rows;
    uint32_t* output_hit_count;
    uint32_t* output_minimum_id;
    uint32_t* output_intersection_count;
    uint32_t* error_seen;
    V4FormalLaunchStatus* status;
    RtdlV4FastRelationControl* fast_control;
};

