static void v4_erase_generated_ptx_entry(
        std::string& ptx, const char* symbol) {
    if (!symbol || !*symbol)
        throw std::runtime_error("V4 diagnostic PTX symbol is empty");
    const std::string marker = std::string(".visible .entry ") + symbol;
    const size_t entry = ptx.find(marker);
    if (entry == std::string::npos ||
            ptx.find(marker, entry + marker.size()) != std::string::npos)
        throw std::runtime_error(
            "V4 diagnostic PTX entry is absent or ambiguous");
    const size_t opening = ptx.find('{', entry + marker.size());
    if (opening == std::string::npos)
        throw std::runtime_error("V4 diagnostic PTX entry lacks a body");
    size_t depth = 0u;
    size_t closing = std::string::npos;
    for (size_t index = opening; index < ptx.size(); ++index) {
        if (ptx[index] == '{') {
            ++depth;
        } else if (ptx[index] == '}') {
            if (depth == 0u)
                throw std::runtime_error(
                    "V4 diagnostic PTX entry has an invalid brace sequence");
            --depth;
            if (depth == 0u) {
                closing = index + 1u;
                break;
            }
        }
    }
    if (closing == std::string::npos)
        throw std::runtime_error("V4 diagnostic PTX entry is unterminated");
    size_t start = ptx.rfind('\n', entry);
    start = start == std::string::npos ? 0u : start + 1u;
    if (start > 0u) {
        const size_t prior_break = ptx.rfind('\n', start - 2u);
        const size_t prior_start =
            prior_break == std::string::npos ? 0u : prior_break + 1u;
        const std::string prior = ptx.substr(prior_start, start - prior_start);
        if (prior.find(".globl") != std::string::npos &&
                prior.find(symbol) != std::string::npos)
            start = prior_start;
    }
    while (closing < ptx.size() &&
            (ptx[closing] == '\n' || ptx[closing] == '\r'))
        ++closing;
    ptx.erase(start, closing - start);
    if (ptx.find(symbol) != std::string::npos)
        throw std::runtime_error(
            "V4 diagnostic PTX symbol survived product projection");
}

static std::string v4_triangle_product_ptx(const std::string& composed_ptx) {
    std::string product = composed_ptx;
    v4_erase_generated_ptx_entry(product, kV4RtdlexeTriangleDiagnosticRaygen);
    v4_erase_generated_ptx_entry(product, kV4RtdlexeTriangleDiagnosticAnyHit);
    v4_erase_generated_ptx_entry(product, kV4RtdlexeTriangleDiagnosticMiss);
    if (product.empty())
        throw std::runtime_error("V4 triangle product PTX is empty");
    return product;
}

static const RtdlexeNativeProducerSpec& v4_rtdlexe_bounded_producer_spec() {
    static const RtdlexeNativeProducerSpec spec = [] {
        auto value = make_native_producer_spec(
            kV4RtdlexeBoundedRaygen, kV4RtdlexeBoundedMiss,
            kV4RtdlexeBoundedIntersection, kV4RtdlexeBoundedAnyHit,
            kV4RtdlexeBoundedClosestHit, 3,
            OPTIX_PRIMITIVE_TYPE_FLAGS_CUSTOM, 1);
        value.family = kV4RtdlexeBoundedFamily;
        value.native_abi = kV4RtdlexeBoundedAbi;
        value.program_bundle = kV4RtdlexeBoundedBundle;
        value.required_invocation_mask = (1u << 1u) | (1u << 6u);
        value.terminal_invocation_mask = (1u << 4u) | (1u << 5u);
        return value;
    }();
    return spec;
}

